const applied = new Set();
const migrations = [
  { id: 1, sql: "CREATE TABLE tasks (...)" },
  { id: 2, sql: "ALTER TABLE tasks ADD COLUMN due DATE" },
];

function migrate() {
  for (const migration of migrations) {
    if (applied.has(migration.id)) continue;
    applied.add(migration.id);
    console.log(`applied migration ${migration.id}`);
  }
  console.log("database is up to date");
}

migrate();
migrate();

function parseImage(ref) {
  const colon = ref.lastIndexOf(":");
  if (colon === -1) return { name: ref, tag: "latest" };
  return { name: ref.slice(0, colon), tag: ref.slice(colon + 1) };
}

for (const ref of ["task-api:1.0.0", "postgres:17", "task-api"]) {
  const { name, tag } = parseImage(ref);
  console.log(`${name} -> ${tag}`);
}

function interpolate(text, env) {
  return text.replace(/\$\{(\w+):\?([^}]*)\}/g, (_, name, message) => {
    if (!env[name]) throw new Error(`required variable ${name} is missing a value: ${message}`);
    return env[name];
  });
}

const template = "postgres://taskapi:${POSTGRES_PASSWORD:?set POSTGRES_PASSWORD in .env}@db:5432/taskapi";
try {
  console.log(interpolate(template, {}));
} catch (error) {
  console.log(error.message);
}
