function isPrivate(ip) {
  return ip.startsWith("10.") || ip.startsWith("172.") || ip.startsWith("192.168.") || ip === "127.0.0.1";
}

function clientIp(socketIp, forwardedFor) {
  if (!forwardedFor || !isPrivate(socketIp)) return socketIp;
  const hops = forwardedFor.split(",").map((part) => part.trim());
  return hops[hops.length - 1];
}

console.log(clientIp("172.18.0.5", "203.0.113.7"));
console.log(clientIp("198.51.100.9", "1.2.3.4"));

