function parseDatabaseUrl(raw) {
  const url = new URL(raw);
  return {
    host: url.hostname,
    port: url.port ? Number(url.port) : 5432,
    database: url.pathname.slice(1),
    user: url.username,
  };
}

// Should print:
// { host: 'db', port: 5432, database: 'taskapi', user: 'taskapi' }
// { host: 'localhost', port: 6543, database: 'shop', user: 'app' }
console.log(parseDatabaseUrl("postgres://taskapi:s3cret@db/taskapi"));
console.log(parseDatabaseUrl("postgres://app:pw@localhost:6543/shop"));

